type tex2 struct {
	u float64
	v float64
}

func clampInt(value, min, max int) int {
	if value < min {
		return min
	}
	if value > max {
		return max
	}
	return value
}

func drawTexel(x, y int, texture []uint32, a, b, c vec4, AUV, BUV, CUV tex2, flatShadePercent float64) {
	if x < 0 || x >= windowWidth || y < 0 || y >= windowHeight {
		return
	}
	p := vec2{x, y}
	aVec2 := vec2FromVec4(a)
	bVec2 := vec2FromVec4(b)
	cVec2 := vec2FromVec4(c)

	weights := barycentricWeights(aVec2, bVec2, cVec2, p)
	alpha, beta, gamma := weights.X, weights.Y, weights.Z
	// Perform the interpolation of all the U/w and V/w values using barycentric weights and a factor of 1/w
	interpolatedU := (AUV.u/a.W)*alpha + (BUV.u/b.W)*beta + (CUV.u/c.W)*gamma
	interpolatedV := (AUV.v/a.W)*alpha + (BUV.v/b.W)*beta + (CUV.v/c.W)*gamma
	// This is 1/w because W (original Z) is not linear
	interpolatedReciprocalW := (1/a.W)*alpha + (1/b.W)*beta + (1/c.W)*gamma

	// Divide back both U and V by 1/w
	interpolatedU /= interpolatedReciprocalW
	interpolatedV /= interpolatedReciprocalW
	// UV is always between 0 and 1 so we need to scale them to texture resolution
	// The overflows here come from the fact that we truncate to (integer) pixels
	// On the border of a triangle a pixel might be outside a triangle which throws the barycentric weights (become bigger than 1)
	// Which then tries to fetch texel outside of bounds of texture array
	texX := int(math.Abs(interpolatedU*float64(textureWidth))) % textureWidth
	texY := int(math.Abs(interpolatedV*float64(textureHeight))) % textureHeight

	// Pixels closer to the viewer need to bigger than the ones further away
	interpolatedReciprocalW = 1 - interpolatedReciprocalW

	// Only draw pixels if depth value if less than the one previously stored in the Z-buffer
	if interpolatedReciprocalW < zBuffer[(windowWidth*y)+x] {
		drawPixel(x, y, lightApplyIntensity(texture[(texY*textureWidth)+texX], flatShadePercent))
		// Update the Z-buffer with 1/w for current pixel
		zBuffer[(windowWidth*y)+x] = interpolatedReciprocalW

	}
}

func loadPngTextureData(path string) error {
	file, err := os.Open(path)
	if err != nil {
		return err
	}
	defer file.Close()

	img, fileFormat, err := image.Decode(file)
	if err != nil {
		return err
	}
	if fileFormat != "png" && fileFormat != "jpeg" {
		return fmt.Errorf("unsupported file format: %s", fileFormat)
	}

	bounds := img.Bounds()
	textureWidth, textureHeight = bounds.Max.X, bounds.Max.Y

	meshTexture = make([]uint32, textureWidth*textureHeight)
	for y := 0; y < textureHeight; y++ {
		for x := 0; x < textureWidth; x++ {
			r16, g16, b16, a16 := img.At(x, y).RGBA()
			r8 := uint8(r16 >> 8)
			g8 := uint8(g16 >> 8)
			b8 := uint8(b16 >> 8)
			a8 := uint8(a16 >> 8)
			meshTexture[(y*textureWidth)+x] = (uint32(a8) << 24) | (uint32(b8) << 16) | (uint32(g8) << 8) | uint32(r8)
		}
	}
	return nil

}
